// Steam + Millennium: meldet laufende Steam-Downloads an App und Web-UI.
// Nur Lesen: die Daten kommen vom Agenten (pc.steam()), nicht aus Dateien.
var laufend = {};
var letzteStatusZeile = "";

// Fortschritt immer mit genau einer Nachkommastelle.
function prozentText(wert) {
  var zahl = Number(wert);
  if (!isFinite(zahl)) {
    return "0.0";
  }
  return zahl.toFixed(1);
}

// Name eines Downloads, mit Ersatzname falls das Feld fehlt.
function nameVon(eintrag, nummer) {
  var name = eintrag && eintrag.name ? String(eintrag.name) : "";
  if (name === "") {
    name = "App " + String(eintrag && eintrag.app_id ? eintrag.app_id : nummer);
  }
  return name;
}

function activate() {
  var status = pc.steam();
  if (!status || !status.detected) {
    pc.log("Steam nicht erkannt - kein Steam-Pfad gefunden.");
    pc.log("> Steam fehlt (Pfad pruefen oder Steam installieren)");
    return;
  }
  pc.log("Steam erkannt: " + String(status.steam_path));
  pc.log("Millennium: " + (status.millennium ? "erkannt" : "nicht erkannt"));
  pc.log("Steam laeuft: " + (status.running ? "ja" : "nein"));
  if (!status.millennium) {
    pc.log("Hinweis: Millennium wird nur erkannt, nicht installiert.");
  }
  laufend = {};
  letzteStatusZeile = "";
}

function tick() {
  var status = pc.steam();
  if (!status || !status.detected) {
    return;
  }
  var liste = status.downloads || [];
  var jetzt = {};
  var i;
  for (i = 0; i < liste.length; i = i + 1) {
    var eintrag = liste[i] || {};
    jetzt[String(eintrag.app_id)] = nameVon(eintrag, i + 1);
  }

  // Fertig gewordene Downloads einmalig melden (Ergebniszeile mit ">").
  var id;
  for (id in laufend) {
    if (!jetzt[id]) {
      pc.log("> Download fertig: " + laufend[id]);
    }
  }
  laufend = jetzt;

  if (!status.downloading || liste.length === 0) {
    if (letzteStatusZeile !== "") {
      pc.log("Keine Downloads mehr aktiv.");
      letzteStatusZeile = "";
    }
    pc.setStatus("");
    return;
  }

  var haupt = liste[0] || {};
  var zeile = "Steam: " + nameVon(haupt, 1) + " " + prozentText(haupt.percent) + " %";
  pc.setStatus(zeile);
  // Nur bei Aenderung loggen, damit das Journal nicht zulaeuft.
  if (zeile !== letzteStatusZeile) {
    var tempo = Number(status.speed_bps) || 0;
    pc.log(zeile + " (" + Math.round(tempo / 1024) + " KB/s)");
    letzteStatusZeile = zeile;
  }
}

function stop() {
  pc.setStatus("");
  pc.log("> Steam-Ueberwachung beendet");
}
